//! Checkpoint 3, behaviour tests: does the library do what SPEC.md says?
//!
//! Run: cargo test --test behaviour
//!
//! All of these must pass, in debug and with `--release`, for the "pass"
//! level in RUBRIC.md. Do not edit this file.

mod common;

use std::cmp::Ordering;
use std::collections::BTreeSet;
use std::error::Error;
use std::sync::mpsc;

use common::within;
use matchday::{DuplicateTeam, Fixtures, League, Outcome, RecordError, Row, Score, Tally};

use Outcome::{Draw, Loss, Win};

/// The league of the example at the top of SPEC.md.
fn example() -> League {
    let mut league = League::new(["Otters", "Kestrels", "Herons"]).unwrap();
    league.record("Kestrels", "Otters", (2, 1)).unwrap();
    league.record("Herons", "Kestrels", (1, 1)).unwrap();
    league.record("Otters", "Herons", (2, 1)).unwrap();
    league
}

fn tally(won: u32, drawn: u32, lost: u32, goals_for: u32, goals_against: u32) -> Tally {
    Tally {
        won,
        drawn,
        lost,
        goals_for,
        goals_against,
    }
}

fn names<'a>(rows: &[Row<'a>]) -> Vec<&'a str> {
    rows.iter().map(|row| row.team).collect()
}

/// Reads a whole `Fixtures` iterator with a time limit, so that an iterator
/// that never ends becomes a failed test instead of a test run that hangs.
fn all_fixtures(teams: &[&str]) -> Vec<(String, String)> {
    let teams: Vec<String> = teams.iter().map(|name| name.to_string()).collect();
    within(10, "reading all fixtures", move || {
        let league = League::new(teams).unwrap();
        let limit = 10_000;
        let pairs: Vec<(String, String)> = league
            .fixtures()
            .take(limit)
            .map(|(home, away)| (home.to_string(), away.to_string()))
            .collect();
        assert!(
            pairs.len() < limit,
            "the iterator yielded {limit} pairs and still did not end"
        );
        pairs
    })
}

fn pair(home: &str, away: &str) -> (String, String) {
    (home.to_string(), away.to_string())
}

// ---------------------------------------------------------------- results

#[test]
fn outcome_not_is_the_view_of_the_other_team() {
    assert_eq!(!Win, Loss);
    assert_eq!(!Loss, Win);
    assert_eq!(!Draw, Draw);
    for outcome in [Win, Draw, Loss] {
        assert_eq!(!!outcome, outcome);
    }
}

#[test]
fn score_from_a_pair() {
    assert_eq!(Score::from((2, 1)), Score { home: 2, away: 1 });
    let score: Score = (0, 255).into();
    assert_eq!(score, Score { home: 0, away: 255 });
}

#[test]
fn score_outcome_is_for_the_home_team() {
    assert_eq!(Score { home: 2, away: 1 }.outcome(), Win);
    assert_eq!(Score { home: 0, away: 1 }.outcome(), Loss);
    assert_eq!(Score { home: 3, away: 3 }.outcome(), Draw);
    assert_eq!(Score { home: 0, away: 0 }.outcome(), Draw);
    assert_eq!(
        Score {
            home: 255,
            away: 254
        }
        .outcome(),
        Win
    );
    assert_eq!(Score { home: 0, away: 255 }.outcome(), Loss);
}

#[test]
fn score_swapped_changes_the_side() {
    let score = Score { home: 4, away: 0 };
    assert_eq!(score.swapped(), Score { home: 0, away: 4 });
    assert_eq!(score.swapped().outcome(), !score.outcome());
    assert_eq!(score.swapped().swapped(), score);
}

// ---------------------------------------------------------------- tallies

#[test]
fn tally_default_is_all_zero() {
    assert_eq!(Tally::default(), tally(0, 0, 0, 0, 0));
    assert_eq!(Tally::default().played(), 0);
    assert_eq!(Tally::default().goal_difference(), 0);
}

#[test]
fn tally_from_a_score_is_the_home_side() {
    assert_eq!(
        Tally::from(Score { home: 2, away: 1 }),
        tally(1, 0, 0, 2, 1)
    );
    assert_eq!(
        Tally::from(Score { home: 0, away: 3 }),
        tally(0, 0, 1, 0, 3)
    );
    assert_eq!(
        Tally::from(Score { home: 1, away: 1 }),
        tally(0, 1, 0, 1, 1)
    );
    assert_eq!(
        Tally::from(Score { home: 255, away: 0 }),
        tally(1, 0, 0, 255, 0)
    );
}

#[test]
fn tally_add_and_add_assign() {
    let a = tally(1, 2, 3, 10, 20);
    let b = tally(4, 0, 1, 5, 6);
    assert_eq!(a + b, tally(5, 2, 4, 15, 26));
    assert_eq!(b + a, a + b);
    assert_eq!(a + Tally::default(), a);
    let mut c = a;
    c += b;
    c += b;
    assert_eq!(c, tally(9, 2, 5, 20, 32));
    assert_eq!(
        a,
        tally(1, 2, 3, 10, 20),
        "`+` and `+=` must not change their right-hand side or a copy"
    );
}

#[test]
fn tally_fields_saturate() {
    let full = tally(u32::MAX, u32::MAX - 1, 7, u32::MAX, 0);
    let more = tally(1, 5, 1, u32::MAX, u32::MAX);
    assert_eq!(
        full + more,
        tally(u32::MAX, u32::MAX, 8, u32::MAX, u32::MAX),
        "a field that would pass u32::MAX stays at u32::MAX; it must not wrap around or panic"
    );
    let mut sum = full;
    sum += more;
    assert_eq!(sum, full + more);
}

#[test]
fn tally_played_and_goal_difference_are_exact() {
    let t = tally(3, 2, 1, 9, 11);
    assert_eq!(t.played(), 6);
    assert_eq!(t.goal_difference(), -2);

    let huge = tally(u32::MAX, u32::MAX, u32::MAX, 0, u32::MAX);
    assert_eq!(
        huge.played(),
        3 * u64::from(u32::MAX),
        "three u32 values can add up to more than a u32 holds"
    );
    assert_eq!(huge.goal_difference(), -i64::from(u32::MAX));
    assert_eq!(
        tally(0, 0, 0, u32::MAX, 0).goal_difference(),
        i64::from(u32::MAX)
    );
}

#[test]
fn tally_sum_of_values_and_of_references() {
    let tallies = [
        tally(1, 0, 0, 2, 1),
        tally(0, 1, 0, 1, 1),
        tally(0, 0, 1, 0, 4),
    ];
    let by_reference: Tally = tallies.iter().sum();
    let by_value: Tally = tallies.into_iter().sum();
    assert_eq!(by_reference, tally(1, 1, 1, 3, 6));
    assert_eq!(by_value, by_reference);
    let nothing: [Tally; 0] = [];
    assert_eq!(nothing.iter().sum::<Tally>(), Tally::default());
    assert_eq!(nothing.into_iter().sum::<Tally>(), Tally::default());
}

// ------------------------------------------------------------------- rows

#[test]
fn row_more_points_is_smaller() {
    let leader = Row {
        team: "zz",
        tally: tally(0, 0, 9, 0, 50),
        points: 10,
    };
    let second = Row {
        team: "aa",
        tally: tally(9, 0, 0, 50, 0),
        points: 9,
    };
    assert!(
        leader < second,
        "more points come first, whatever the other fields say"
    );
    assert_eq!(leader.cmp(&second), Ordering::Less);
    assert_eq!(second.cmp(&leader), Ordering::Greater);
    assert_eq!(leader.min(second), leader);
}

#[test]
fn row_ties_are_broken_in_the_order_of_the_spec() {
    // Equal points: the goal difference decides, before goals for.
    let a = Row {
        team: "b",
        tally: tally(1, 0, 0, 2, 0),
        points: 3,
    };
    let b = Row {
        team: "a",
        tally: tally(1, 0, 0, 5, 4),
        points: 3,
    };
    assert!(
        a < b,
        "difference +2 stands above difference +1, although 5 goals are more than 2"
    );

    // Equal points and difference: goals for decide, before the name.
    let a = Row {
        team: "b",
        tally: tally(1, 0, 0, 4, 3),
        points: 3,
    };
    let b = Row {
        team: "a",
        tally: tally(1, 0, 0, 2, 1),
        points: 3,
    };
    assert!(
        a < b,
        "with the same difference, 4 goals stand above 2 goals"
    );

    // A negative difference is below a difference of zero.
    let a = Row {
        team: "b",
        tally: tally(0, 1, 0, 0, 0),
        points: 1,
    };
    let b = Row {
        team: "a",
        tally: tally(0, 1, 0, 3, 5),
        points: 1,
    };
    assert!(a < b, "difference 0 stands above difference -2");

    // Everything equal: the name decides, in the order of str.
    let a = Row {
        team: "Zebras",
        tally: tally(1, 0, 0, 1, 0),
        points: 3,
    };
    let b = Row {
        team: "ants",
        tally: tally(1, 0, 0, 1, 0),
        points: 3,
    };
    assert!(a < b, "\"Zebras\" < \"ants\" in the order of str");
}

#[test]
fn row_order_uses_the_points_of_the_row() {
    // The points come from the league's rule; the order must not compute
    // its own points from the tally.
    let a = Row {
        team: "a",
        tally: tally(0, 0, 3, 0, 9),
        points: 7,
    };
    let b = Row {
        team: "b",
        tally: tally(3, 0, 0, 9, 0),
        points: 2,
    };
    assert!(a < b);
}

#[test]
fn row_goal_difference_is_compared_exactly() {
    let a = Row {
        team: "a",
        tally: tally(0, 0, 0, u32::MAX, 0),
        points: 0,
    };
    let b = Row {
        team: "b",
        tally: tally(0, 0, 0, 0, u32::MAX),
        points: 0,
    };
    let c = Row {
        team: "c",
        tally: tally(0, 0, 0, 5, 5),
        points: 0,
    };
    assert!(
        a < c && c < b,
        "+4294967295 is above 0, and 0 is above -4294967295"
    );
    let mut rows = [b, c, a];
    rows.sort();
    assert_eq!(names(&rows), ["a", "c", "b"]);
}

#[test]
fn row_equality_and_sorting() {
    let a = Row {
        team: "a",
        tally: tally(1, 0, 0, 2, 1),
        points: 3,
    };
    let same = Row {
        team: "a",
        tally: tally(1, 0, 0, 2, 1),
        points: 3,
    };
    let b = Row {
        team: "b",
        tally: tally(1, 0, 0, 2, 1),
        points: 3,
    };
    assert_eq!(a, same);
    assert_eq!(a.cmp(&same), Ordering::Equal);
    assert_eq!(a.partial_cmp(&same), Some(Ordering::Equal));
    assert_ne!(a, b);
    assert_eq!(a.partial_cmp(&b), Some(Ordering::Less));
    assert!(a <= same);
    assert!(a >= same);
    assert!(a < b && b > a);

    let set: BTreeSet<Row<'_>> = [b, a, same].into_iter().collect();
    assert_eq!(set.into_iter().collect::<Vec<_>>(), [a, b]);
}

// --------------------------------------------------------------- new league

#[test]
fn new_accepts_str_and_string_from_any_iterator() {
    let from_array = League::new(["b", "a"]).unwrap();
    let from_vec = League::new(vec![String::from("b"), String::from("a")]).unwrap();
    let owned = [String::from("b"), String::from("a")];
    let from_references = League::new(owned.iter().map(String::as_str)).unwrap();
    let from_chars = League::new("ba".chars()).unwrap();
    for league in [&from_array, &from_vec, &from_references, &from_chars] {
        assert_eq!(league.teams().collect::<Vec<_>>(), ["a", "b"]);
    }
}

#[test]
fn new_league_is_all_zero() {
    let league = League::new(["Otters", "Herons"]).unwrap();
    assert_eq!(league.tally("Otters"), Some(&Tally::default()));
    assert_eq!(league.tally("Herons"), Some(&Tally::default()));
    assert_eq!(league.tally("otters"), None, "names are compared exactly");
    assert_eq!(league.form("Otters").unwrap().count(), 0);
}

#[test]
fn new_league_may_be_empty() {
    let league = League::new(Vec::<String>::new()).unwrap();
    assert_eq!(
        league.teams().count(),
        0,
        "a league without teams has no names"
    );
    assert!(league.standings().is_empty());
    assert!(league.top(3).is_empty());
    assert_eq!(league.tally(""), None);
}

#[test]
fn new_rejects_a_name_that_occurs_twice() {
    let result = League::new(["Otters", "Herons", "Owls", "Herons", "Otters"]);
    assert_eq!(
        result.err(),
        Some(DuplicateTeam("Herons".to_string())),
        "Herons is the first name that is seen for the second time"
    );
    assert!(
        League::new(["", "x", ""]).is_err(),
        "the empty string is a name like any other"
    );
    assert!(League::new(["Otters", "otters", "OTTERS"]).is_ok());
}

#[test]
fn teams_are_in_str_order() {
    let league = League::new(["ants", "Zebras", "", "Émeus", "zebras", "Ants"]).unwrap();
    assert_eq!(
        league.teams().collect::<Vec<_>>(),
        ["", "Ants", "Zebras", "ants", "zebras", "Émeus"],
        "the order of str is byte by byte: capital letters first, non-ASCII letters last"
    );
}

// ----------------------------------------------------------------- record

#[test]
fn record_updates_both_teams() {
    let mut league = League::new(["Otters", "Kestrels", "Herons"]).unwrap();
    assert_eq!(
        league.record("Kestrels", "Otters", Score { home: 2, away: 1 }),
        Ok(())
    );
    assert_eq!(league.tally("Kestrels"), Some(&tally(1, 0, 0, 2, 1)));
    assert_eq!(
        league.tally("Otters"),
        Some(&tally(0, 0, 1, 1, 2)),
        "the away team sees the score swapped"
    );
    assert_eq!(league.tally("Herons"), Some(&Tally::default()));
}

#[test]
fn record_accepts_a_pair_as_score() {
    let mut league = League::new(["a", "b"]).unwrap();
    league.record("a", "b", (0, 0)).unwrap();
    league.record("b", "a", (3, 5)).unwrap();
    assert_eq!(league.tally("a"), Some(&tally(1, 1, 0, 5, 3)));
    assert_eq!(league.tally("b"), Some(&tally(0, 1, 1, 3, 5)));
}

#[test]
fn record_the_example_of_the_spec() {
    let league = example();
    assert_eq!(league.tally("Kestrels"), Some(&tally(1, 1, 0, 3, 2)));
    assert_eq!(league.tally("Otters"), Some(&tally(1, 0, 1, 3, 3)));
    assert_eq!(league.tally("Herons"), Some(&tally(0, 1, 1, 2, 3)));
}

#[test]
fn record_the_same_teams_may_meet_again() {
    let mut league = League::new(["a", "b"]).unwrap();
    for _ in 0..300 {
        league.record("a", "b", (255, 1)).unwrap();
    }
    assert_eq!(league.tally("a"), Some(&tally(300, 0, 0, 76_500, 300)));
    assert_eq!(league.tally("b"), Some(&tally(0, 0, 300, 300, 76_500)));
}

#[test]
fn record_errors_in_the_order_of_the_spec() {
    let mut league = League::new(["Otters", "Herons"]).unwrap();
    let unknown = |name: &str| Err(RecordError::UnknownTeam(name.to_string()));
    assert_eq!(league.record("Owls", "Otters", (1, 0)), unknown("Owls"));
    assert_eq!(league.record("Otters", "Owls", (1, 0)), unknown("Owls"));
    assert_eq!(
        league.record("Owls", "Ibises", (1, 0)),
        unknown("Owls"),
        "home is checked first"
    );
    assert_eq!(
        league.record("Owls", "Owls", (1, 0)),
        unknown("Owls"),
        "an unknown team is reported before the two names are compared"
    );
    assert_eq!(
        league.record("Otters", "Otters", (1, 0)),
        Err(RecordError::SameTeam)
    );
    assert_eq!(league.record("otters", "Herons", (1, 0)), unknown("otters"));
}

#[test]
fn record_failure_changes_nothing() {
    let mut league = example();
    let before: Vec<Tally> = league.standings().iter().map(|row| row.tally).collect();
    let _ = league.record("Kestrels", "Owls", (9, 0));
    let _ = league.record("Owls", "Kestrels", (9, 0));
    let _ = league.record("Kestrels", "Kestrels", (9, 0));
    let after: Vec<Tally> = league.standings().iter().map(|row| row.tally).collect();
    assert_eq!(before, after, "a failed `record` must not touch any tally");
    assert_eq!(
        league.form("Kestrels").unwrap().collect::<Vec<_>>(),
        [Win, Draw],
        "a failed `record` must not add to the form either"
    );
}

#[test]
fn index_reads_a_tally() {
    let league = example();
    assert_eq!(league["Kestrels"], tally(1, 1, 0, 3, 2));
    assert_eq!(league["Herons"].goal_difference(), -1);
    let name = String::from("Otters");
    assert_eq!(league[name.as_str()].played(), 2);
}

#[test]
#[should_panic(expected = "Nowhere Rovers")]
fn index_panics_for_an_unknown_team_and_names_it() {
    let league = example();
    let _ = league["Nowhere Rovers"];
}

// ------------------------------------------------------------------- form

#[test]
fn form_is_seen_from_each_team_oldest_first() {
    let league = example();
    assert_eq!(
        league.form("Kestrels").unwrap().collect::<Vec<_>>(),
        [Win, Draw]
    );
    assert_eq!(
        league.form("Otters").unwrap().collect::<Vec<_>>(),
        [Loss, Win]
    );
    assert_eq!(
        league.form("Herons").unwrap().collect::<Vec<_>>(),
        [Draw, Loss]
    );
    assert!(league.form("Owls").is_none());
}

#[test]
fn form_keeps_the_last_five() {
    let mut league = League::new(["a", "b"]).unwrap();
    assert_eq!(League::FORM_LEN, 5);
    // a: W W L D L W W
    for score in [(1, 0), (2, 0), (0, 1), (1, 1), (0, 2), (3, 0), (4, 0)] {
        league.record("a", "b", score).unwrap();
    }
    assert_eq!(
        league.form("a").unwrap().collect::<Vec<_>>(),
        [Loss, Draw, Loss, Win, Win]
    );
    assert_eq!(
        league.form("b").unwrap().collect::<Vec<_>>(),
        [Win, Draw, Win, Loss, Loss]
    );
    assert_eq!(
        league.tally("a").unwrap().played(),
        7,
        "the tally still counts every match"
    );
}

#[test]
fn form_reads_from_both_ends_and_knows_its_length() {
    let mut league = League::new(["a", "b"]).unwrap();
    for score in [(1, 0), (0, 1), (1, 1)] {
        league.record("a", "b", score).unwrap();
    }
    let mut form = league.form("a").unwrap();
    assert_eq!(form.len(), 3, "three matches were recorded");
    assert_eq!(
        form.next_back(),
        Some(Draw),
        "the most recent outcome is at the back"
    );
    assert_eq!(form.next(), Some(Win));
    assert_eq!(form.len(), 1, "two of the three outcomes have been taken");
    assert_eq!(form.next(), Some(Loss));
    assert_eq!(form.next(), None);
    assert_eq!(form.next_back(), None);

    let newest_first: Vec<Outcome> = league.form("b").unwrap().rev().collect();
    assert_eq!(newest_first, [Draw, Win, Loss]);
}

