#[test]
fn standings_of_a_new_league_are_in_name_order() {
    let league = League::new(["c", "a", "b"]).unwrap();
    let rows = league.standings();
    assert_eq!(names(&rows), ["a", "b", "c"]);
    assert!(
        rows.iter()
            .all(|row| row.points == 0 && row.tally == Tally::default())
    );
}

#[test]
fn standings_break_ties_by_difference_then_goals() {
    let mut league = League::new(["a", "b", "c", "d", "e", "f"]).unwrap();
    league.record("c", "a", (2, 1)).unwrap(); // c: 3 points, +1, 2 goals
    league.record("d", "b", (1, 0)).unwrap(); // d: 3 points, +1, 1 goal
    league.record("f", "e", (3, 0)).unwrap(); // f: 3 points, +3
    assert_eq!(
        names(&league.standings()),
        ["f", "c", "d", "a", "b", "e"],
        "winners by difference then goals: f, c, d. Losers: a (-1, 1 goal), b (-1, 0 goals), e (-3)"
    );
}

#[test]
fn standings_use_the_rule_of_the_league() {
    let play = |league: &mut League| {
        league.record("a", "b", (1, 0)).unwrap();
        league.record("c", "a", (2, 2)).unwrap();
        league.record("c", "b", (0, 0)).unwrap();
        league.record("d", "c", (1, 1)).unwrap();
    };
    // a: 1 win, 1 draw. c: 3 draws. b: 1 draw, 1 loss. d: 1 draw.
    let mut standard = League::new(["a", "b", "c", "d"]).unwrap();
    play(&mut standard);
    let rows = standard.standings();
    assert_eq!(names(&rows), ["a", "c", "d", "b"]);
    assert_eq!(
        rows.iter().map(|row| row.points).collect::<Vec<_>>(),
        [4, 3, 1, 1]
    );

    // Two points for a draw, one for a win.
    let mut generous = League::new(["a", "b", "c", "d"])
        .unwrap()
        .with_rule(|t| u64::from(t.won) + 2 * u64::from(t.drawn));
    play(&mut generous);
    let rows = generous.standings();
    assert_eq!(names(&rows), ["c", "a", "d", "b"]);
    assert_eq!(
        rows.iter().map(|row| row.points).collect::<Vec<_>>(),
        [6, 3, 2, 2]
    );
}

#[test]
fn rule_may_capture_and_return_large_numbers() {
    let bonus = [u64::MAX - 10, 5];
    let mut league = League::new(["a", "b"])
        .unwrap()
        .with_rule(move |t| bonus[t.won as usize % 2]);
    league.record("b", "a", (1, 0)).unwrap();
    let rows = league.standings();
    assert_eq!((rows[0].team, rows[0].points), ("a", u64::MAX - 10));
    assert_eq!((rows[1].team, rows[1].points), ("b", 5));
}

#[test]
fn top_is_the_start_of_the_standings() {
    let mut league = League::new(["a", "b", "c", "d", "e", "f", "g"]).unwrap();
    for (home, away, score) in [
        ("a", "b", (1, 0)),
        ("c", "d", (4, 4)),
        ("e", "f", (0, 2)),
        ("g", "a", (1, 3)),
        ("b", "c", (2, 2)),
        ("f", "d", (1, 0)),
        ("e", "g", (5, 0)),
    ] {
        league.record(home, away, score).unwrap();
    }
    let all = league.standings();
    assert_eq!(names(&all), ["a", "f", "e", "c", "d", "b", "g"]);
    for k in 0..=7 {
        assert_eq!(
            league.top(k),
            all[..k],
            "top({k}) must be the first {k} rows of standings()"
        );
    }
    assert_eq!(league.top(8), all);
    assert_eq!(league.top(1000), all);
    assert_eq!(
        league.top(usize::MAX),
        all,
        "every k is valid, also usize::MAX"
    );
}

#[test]
fn standings_total_wins_equal_total_losses() {
    let mut league = League::new(["a", "b", "c", "d"]).unwrap();
    let teams = ["a", "b", "c", "d"];
    for round in 0u8..40 {
        let home = teams[usize::from(round) % 4];
        let away = teams[usize::from(round / 4 + round + 1) % 4];
        if home != away {
            league.record(home, away, (round % 5, round % 3)).unwrap();
        }
    }
    let total: Tally = league.standings().iter().map(|row| row.tally).sum();
    assert_eq!(total.won, total.lost);
    assert_eq!(total.goals_for, total.goals_against);
    assert_eq!(total.drawn % 2, 0);
    let direct: Tally = teams.iter().map(|&team| &league[team]).sum();
    assert_eq!(direct, total);
}

// -------------------------------------------------------------- observers

#[test]
fn observers_see_every_recorded_match() {
    let (sender, receiver) = mpsc::channel();
    let mut league = League::new(["a", "b", "c"]).unwrap();
    league.record("a", "b", (9, 9)).unwrap(); // before registration: not seen
    league.on_record(move |home, away, score| {
        sender
            .send(format!("{home} {}:{} {away}", score.home, score.away))
            .unwrap();
    });
    league.record("a", "b", (2, 1)).unwrap();
    league.record("c", "a", Score { home: 0, away: 0 }).unwrap();
    assert_eq!(
        receiver.try_iter().collect::<Vec<_>>(),
        ["a 2:1 b", "c 0:0 a"]
    );
}

#[test]
fn observers_run_in_order_and_may_keep_state() {
    let (sender, receiver) = mpsc::channel();
    let mut league = League::new(["a", "b"]).unwrap();
    for label in ["first", "second", "third"] {
        let sender = sender.clone();
        let mut calls = 0;
        // `calls` lives inside the closure and changes on every call, so
        // this is an `FnMut` closure and not an `Fn` closure.
        league.on_record(move |_, _, _| {
            calls += 1;
            sender.send((label, calls)).unwrap();
        });
    }
    league.record("a", "b", (1, 0)).unwrap();
    league.record("b", "a", (1, 0)).unwrap();
    assert_eq!(
        receiver.try_iter().collect::<Vec<_>>(),
        [
            ("first", 1),
            ("second", 1),
            ("third", 1),
            ("first", 2),
            ("second", 2),
            ("third", 2)
        ]
    );
}

#[test]
fn observers_are_not_called_for_a_failed_record() {
    let (sender, receiver) = mpsc::channel();
    let mut league = League::new(["a", "b"]).unwrap();
    league
        .on_record(move |home, away, _| sender.send((home.to_string(), away.to_string())).unwrap());
    let _ = league.record("a", "a", (1, 0));
    let _ = league.record("a", "x", (1, 0));
    let _ = league.record("x", "a", (1, 0));
    assert_eq!(
        receiver.try_iter().count(),
        0,
        "no observer may be called for a `record` that returned Err"
    );
    league.record("b", "a", (1, 0)).unwrap();
    assert_eq!(receiver.try_iter().collect::<Vec<_>>(), [pair("b", "a")]);
}

