#[test]
fn error_messages() {
    assert_eq!(
        DuplicateTeam("Otters".to_string()).to_string(),
        "team listed twice: Otters"
    );
    assert_eq!(
        RecordError::UnknownTeam("Owls".to_string()).to_string(),
        "unknown team: Owls"
    );
    assert_eq!(
        RecordError::SameTeam.to_string(),
        "a team cannot play against itself"
    );
    assert_eq!(
        RecordError::UnknownTeam(String::new()).to_string(),
        "unknown team: "
    );
}

#[test]
fn errors_are_std_errors_without_source() {
    let errors: [Box<dyn Error + Send + Sync>; 3] = [
        Box::new(DuplicateTeam("x".to_string())),
        Box::new(RecordError::UnknownTeam("x".to_string())),
        Box::new(RecordError::SameTeam),
    ];
    assert!(errors.iter().all(|error| error.source().is_none()));

    fn season() -> Result<u64, Box<dyn Error>> {
        let mut league = League::new(["a", "b"])?;
        league.record("a", "b", (1, 0))?;
        league.record("a", "c", (1, 0))?;
        Ok(league["a"].played())
    }
    assert_eq!(season().unwrap_err().to_string(), "unknown team: c");
}
